1	// Package server exposes the frozen public surface of SignalWatch.
2	//
3	// Besides the baseline process health check, the server accepts in-memory
4	// metric samples at /api/v1/metrics. All new responses use JSON. Metric state
5	// is process-local and is lost on restart.
6	package server
7	
8	import (
9		"bytes"
10		"encoding/json"
11		"io"
12		"math"
13		"mime"
14		"net/http"
15		"net/url"
16		"regexp"
17		"sort"
18		"strconv"
19		"strings"
20		"sync"
21	)
22	
23	// Version is the baseline release identifier.
24	const Version = "0.1.0"
25	
26	const metricsPath = "/api/v1/metrics"
27	
28	var identPattern = regexp.MustCompile(`^[a-zA-Z_][a-zA-Z0-9_]*$`)
29	
30	type health struct {
31		Status  string `json:"status"`
32		Service string `json:"service"`
33		Version string `json:"version"`
34	}
35	
36	// series is one uniquely identified time series: name + full label set.
37	type series struct {
38		name   string
39		typ    string
40		labels map[string]string
41	
42		// counter/gauge state
43		value float64
44	
45		// histogram state
46		bucketBounds []float64 // strictly increasing, fixed at first write
47		bucketCounts []int64   // cumulative counts per bound, len == len(bucketBounds)
48		count        int64
49		sum          float64
50	}
51	
52	type metricStore struct {
53		mu     sync.RWMutex
54		series map[string]*series
55	
56		// alert rules keyed by rule id; guarded by mu so rule replacement and
57		// alert evaluation are atomic with metric commits.
58		rules map[string]*alertRule
59	
60		// silences keyed by silence id; same lock so alert evaluation reads
61		// metrics, rules and silences from one consistent snapshot.
62		silences map[string]*silence
63	
64		// inhibit rules keyed by rule id; same lock so alert evaluation also
65		// reads inhibit rules from the same consistent snapshot.
66		inhibitions map[string]*inhibitRule
67	
68		// notification routes keyed by route id; same lock so the notification
69		// plan reads routes from the same snapshot as alert evaluation.
70		notificationRoutes map[string]*notificationRoute
71	
72		// SLO definitions keyed by SLO id; same lock so status evaluation reads
73		// definitions and counters from one consistent snapshot.
74		slos map[string]*sloDefinition
75	
76		// Log entries keyed by entry id; same lock so log commits and retrieval
77		// read one consistent snapshot. logOrder is the submission-order FIFO
78		// of ids used for eviction; logSeq is the commit sequence that anchors
79		// paginated read snapshots.
80		logs     map[string]*logEntry
81		logOrder []string
82		logSeq   int64
83	}
84	
85	func newMetricStore() *metricStore {
86		return &metricStore{
87			series:             make(map[string]*series),
88			rules:              make(map[string]*alertRule),
89			silences:           make(map[string]*silence),
90			inhibitions:        make(map[string]*inhibitRule),
91			notificationRoutes: make(map[string]*notificationRoute),
92			slos:               make(map[string]*sloDefinition),
93			logs:               make(map[string]*logEntry),
94		}
95	}
96	
97	// validatedSample is a sample that passed all format and value checks.
98	type validatedSample struct {
99		key     string
100		name    string
101		typ     string
102		labels  map[string]string
103		value   float64
104		buckets []float64 // non-nil for histograms
105	}
106	
107	// checkAndApply validates the batch against the current state (and against
108	// itself) and then commits it in array order. A false result signals a type or
109	// bucket-boundary conflict; in that case no state is mutated.
110	func (s *metricStore) checkAndApply(batch []validatedSample) bool {
111		s.mu.Lock()
112		defer s.mu.Unlock()
113	
114		// First pass: conflict detection against committed state and earlier
115		// samples in the same batch.
116		resolved := make(map[string]*series, len(batch))
117		for _, sm := range batch {
118			existing, ok := s.series[sm.key]
119			if !ok {
120				if shadow, seen := resolved[sm.key]; seen {
121					existing, ok = shadow, true
122				}
123			}
124			if ok {
125				if existing.typ != sm.typ {
126					return false
127				}
128				if sm.typ == "histogram" && !equalBuckets(existing.bucketBounds, sm.buckets) {
129					return false
130				}
131				resolved[sm.key] = existing
132				continue
133			}
134			resolved[sm.key] = &series{typ: sm.typ, bucketBounds: sm.buckets}
135		}
136	
137		// Second pass: commit in order.
138		for _, sm := range batch {
139			cur, ok := s.series[sm.key]
140			if !ok {
141				cur = &series{
142					name:         sm.name,
143					typ:          sm.typ,
144					labels:       sm.labels,
145					bucketBounds: append([]float64(nil), sm.buckets...),
146				}
147				if sm.typ == "histogram" {
148					cur.bucketCounts = make([]int64, len(sm.buckets))
149				}
150				s.series[sm.key] = cur
151			}
152			switch sm.typ {
153			case "counter":
154				cur.value += sm.value
155			case "gauge":
156				cur.value = sm.value
157			case "histogram":
158				cur.count++
159				cur.sum += sm.value
160				for i, bound := range cur.bucketBounds {
161					if sm.value <= bound {
162						cur.bucketCounts[i]++
163					}
164				}
165			}
166		}
167		return true
168	}
169	
170	type seriesOutput struct {
171		Name    string            `json:"name"`
172		Type    string            `json:"type"`
173		Labels  map[string]string `json:"labels"`
174		Value   *float64          `json:"value,omitempty"`
175		Count   *int64            `json:"count,omitempty"`
176		Sum     *float64          `json:"sum,omitempty"`
177		Buckets []bucketOutput    `json:"buckets,omitempty"`
178	}
179	
180	type bucketOutput struct {
181		LE    float64 `json:"le"`
182		Count int64   `json:"count"`
183	}
184	
185	// query returns matching series as ready-to-encode outputs. A series matches
186	// when its name equals name exactly and it contains every selector label.
187	func (s *metricStore) query(name string, selector map[string]string) []seriesOutput {
188		s.mu.RLock()
189		defer s.mu.RUnlock()
190	
191		out := make([]seriesOutput, 0)
192		for _, cur := range s.series {
193			if cur.name != name {
194				continue
195			}
196			matched := true
197			for k, v := range selector {
198				got, ok := cur.labels[k]
199				if !ok || got != v {
200					matched = false
201					break
202				}
203			}
204			if !matched {
205				continue
206			}
207			item := seriesOutput{
208				Name:   cur.name,
209				Type:   cur.typ,
210				Labels: copyLabels(cur.labels),
211			}
212			switch cur.typ {
213			case "counter", "gauge":
214				v := cur.value
215				item.Value = &v
216			case "histogram":
217				c, sum := cur.count, cur.sum
218				item.Count = &c
219				item.Sum = &sum
220				item.Buckets = make([]bucketOutput, len(cur.bucketBounds))
221				for i, bound := range cur.bucketBounds {
222					item.Buckets[i] = bucketOutput{LE: bound, Count: cur.bucketCounts[i]}
223				}
224			}
225			out = append(out, item)
226		}
227	
228		sort.Slice(out, func(i, j int) bool {
229			return compareLabels(out[i].Labels, out[j].Labels) < 0
230		})
231		return out
232	}
233	
234	// compareLabels imposes a normalized lexicographic order on full label sets:
235	// keys are sorted, then (key, value) pairs are compared element-wise, and a
236	// shorter pair list sorts first when it is a prefix of a longer one.
237	func compareLabels(a, b map[string]string) int {
238		ka := sortedKeys(a)
239		kb := sortedKeys(b)
240		n := len(ka)
241		if len(kb) < n {
242			n = len(kb)
243		}
244		for i := 0; i < n; i++ {
245			if ka[i] != kb[i] {
246				return strings.Compare(ka[i], kb[i])
247			}
248			if a[ka[i]] != b[kb[i]] {
249				return strings.Compare(a[ka[i]], b[kb[i]])
250			}
251		}
252		switch {
253		case len(ka) < len(kb):
254			return -1
255		case len(ka) > len(kb):
256			return 1
257		default:
258			return 0
259		}
260	}
261	
262	func sortedKeys(m map[string]string) []string {
263		keys := make([]string, 0, len(m))
264		for k := range m {
265			keys = append(keys, k)
266		}
267		sort.Strings(keys)
268		return keys
269	}
270	
271	func copyLabels(in map[string]string) map[string]string {
272		out := make(map[string]string, len(in))
273		for k, v := range in {
274			out[k] = v
275		}
276		return out
277	}
278	
279	// seriesKey builds a collision-free identity from name + unordered labels.
280	// Name and label keys are restricted to [a-zA-Z0-9_] and cannot contain NUL,
281	// so length-prefixed values remove any ambiguity from arbitrary label values.
282	func seriesKey(name string, labels map[string]string) string {
283		var b strings.Builder
284		b.WriteString(name)
285		for _, k := range sortedKeys(labels) {
286			b.WriteByte(0)
287			b.WriteString(k)
288			b.WriteByte(0)
289			v := labels[k]
290			b.WriteString(strconv.Itoa(len(v)))
291			b.WriteByte(0)
292			b.WriteString(v)
293		}
294		return b.String()
295	}
296	
297	func equalBuckets(a, b []float64) bool {
298		if len(a) != len(b) {
299			return false
300		}
301		for i := range a {
302			if a[i] != b[i] {
303				return false
304			}
305		}
306		return true
307	}
308	
309	// Handler returns the HTTP surface served by SignalWatch.
310	func Handler() http.Handler {
311		return newHandler(newTenantRegistry())
312	}
313	
314	func newHandler(registry *tenantRegistry) http.Handler {
315		mux := http.NewServeMux()
316	
317		mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
318			if r.Method != http.MethodGet {
319				w.Header().Set("Allow", http.MethodGet)
320				http.Error(w, `{"error":{"code":"method_not_allowed"}}`, http.StatusMethodNotAllowed)
321				return
322			}
323			w.Header().Set("Content-Type", "application/json; charset=utf-8")
324			_ = json.NewEncoder(w).Encode(health{Status: "ok", Service: "signalwatch", Version: Version})
325		})
326	
327		mux.HandleFunc(metricsPath, func(w http.ResponseWriter, r *http.Request) {
328			switch r.Method {
329			case http.MethodGet:
330				handleMetricsGet(w, r)
331			case http.MethodPost:
332				handleMetricsPost(w, r)
333			default:
334				w.Header().Set("Allow", "GET, POST")
335				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
336			}
337		})
338	
339		registerAlertHandlers(mux)
340		registerSilenceHandlers(mux)
341		registerInhibitHandlers(mux)
342		registerNotificationRouteHandlers(mux)
343		registerSLOHandlers(mux)
344		registerQueryHandler(mux)
345		registerLogHandlers(mux)
346	
347		return withTenants(mux, registry)
348	}
349	
350	func handleMetricsPost(w http.ResponseWriter, r *http.Request) {
351		store := tenantStore(r)
352		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
353		if err != nil || mediaType != "application/json" {
354			writeAPIError(w, "unsupported_media_type", http.StatusUnsupportedMediaType)
355			return
356		}
357	
358		body, err := io.ReadAll(r.Body)
359		if err != nil {
360			writeAPIError(w, "invalid_metrics", http.StatusBadRequest)
361			return
362		}
363	
364		batch, ok := decodeMetricsBatch(body)
365		if !ok {
366			writeAPIError(w, "invalid_metrics", http.StatusBadRequest)
367			return
368		}
369	
370		if !store.checkAndApply(batch) {
371			writeAPIError(w, "metric_conflict", http.StatusConflict)
372			return
373		}
374	
375		w.Header().Set("Content-Type", "application/json; charset=utf-8")
376		w.WriteHeader(http.StatusAccepted)
377		_ = json.NewEncoder(w).Encode(map[string]int{"accepted": len(batch)})
378	}
379	
380	type metricsEnvelope struct {
381		Samples *[]json.RawMessage `json:"samples"`
382	}
383	
384	type rawSample struct {
385		Name    *string            `json:"name"`
386		Type    *string            `json:"type"`
387		Labels  *map[string]string `json:"labels"`
388		Value   *float64           `json:"value"`
389		Buckets *[]float64         `json:"buckets"`
390	}
391	
392	// decodeMetricsBatch performs every format and value check. It never returns a
393	// partially validated batch.
394	func decodeMetricsBatch(body []byte) ([]validatedSample, bool) {
395		var env metricsEnvelope
396		if !strictDecode(body, &env) || env.Samples == nil || len(*env.Samples) == 0 {
397			return nil, false
398		}
399	
400		batch := make([]validatedSample, 0, len(*env.Samples))
401		for _, raw := range *env.Samples {
402			var sm rawSample
403			if !strictDecode(raw, &sm) {
404				return nil, false
405			}
406			if sm.Name == nil || sm.Type == nil || sm.Labels == nil || sm.Value == nil {
407				return nil, false
408			}
409			name, typ := *sm.Name, *sm.Type
410			if !identPattern.MatchString(name) {
411				return nil, false
412			}
413			if typ != "counter" && typ != "gauge" && typ != "histogram" {
414				return nil, false
415			}
416			labels := *sm.Labels
417			if labels == nil {
418				return nil, false // explicit null labels
419			}
420			for k := range labels {
421				if !identPattern.MatchString(k) {
422					return nil, false
423				}
424			}
425			value := *sm.Value
426			if math.IsNaN(value) || math.IsInf(value, 0) {
427				return nil, false // encoding/json already rejects NaN/Inf tokens
428			}
429			if typ == "counter" && value < 0 {
430				return nil, false
431			}
432	
433			var buckets []float64
434			if typ == "histogram" {
435				if sm.Buckets == nil || !validBuckets(*sm.Buckets) {
436					return nil, false
437				}
438				buckets = append([]float64(nil), (*sm.Buckets)...)
439			} else if sm.Buckets != nil {
440				return nil, false // buckets only valid on histograms
441			}
442	
443			batch = append(batch, validatedSample{
444				key:     seriesKey(name, labels),
445				name:    name,
446				typ:     typ,
447				labels:  copyLabels(labels),
448				value:   value,
449				buckets: buckets,
450			})
451		}
452		return batch, true
453	}
454	
455	func validBuckets(buckets []float64) bool {
456		if len(buckets) == 0 {
457			return false
458		}
459		prev := math.Inf(-1)
460		for _, b := range buckets {
461			if math.IsNaN(b) || math.IsInf(b, 0) || b <= prev {
462				return false
463			}
464			prev = b
465		}
466		return true
467	}
468	
469	// strictDecode decodes JSON, rejecting unknown fields, multiple/ trailing
470	// values and non-object payloads for struct targets.
471	func strictDecode(data []byte, target any) bool {
472		dec := json.NewDecoder(bytes.NewReader(data))
473		dec.DisallowUnknownFields()
474		if err := dec.Decode(target); err != nil {
475			return false
476		}
477		var extra json.RawMessage
478		if err := dec.Decode(&extra); err != io.EOF {
479			return false
480		}
481		return true
482	}
483	
484	func handleMetricsGet(w http.ResponseWriter, r *http.Request) {
485		store := tenantStore(r)
486		values, err := url.ParseQuery(r.URL.RawQuery)
487		if err != nil {
488			writeAPIError(w, "invalid_query", http.StatusBadRequest)
489			return
490		}
491	
492		names := values["name"]
493		if len(names) == 0 || !identPattern.MatchString(names[0]) {
494			writeAPIError(w, "invalid_query", http.StatusBadRequest)
495			return
496		}
497	
498		selector := make(map[string]string)
499		for key, vals := range values {
500			if !strings.HasPrefix(key, "label.") {
501				continue
502			}
503			labelKey := strings.TrimPrefix(key, "label.")
504			if !identPattern.MatchString(labelKey) {
505				writeAPIError(w, "invalid_query", http.StatusBadRequest)
506				return
507			}
508			for _, v := range vals[1:] {
509				if v != vals[0] {
510					writeAPIError(w, "invalid_query", http.StatusBadRequest)
511					return
512				}
513			}
514			selector[labelKey] = vals[0]
515		}
516	
517		seriesList := store.query(names[0], selector)
518		w.Header().Set("Content-Type", "application/json; charset=utf-8")
519		_ = json.NewEncoder(w).Encode(map[string]any{"series": seriesList})
520	}
521	
522	func writeAPIError(w http.ResponseWriter, code string, status int) {
523		w.Header().Set("Content-Type", "application/json; charset=utf-8")
524		w.WriteHeader(status)
525		_ = json.NewEncoder(w).Encode(map[string]any{"error": map[string]string{"code": code}})
526	}
