	case now.Before(s.endsAt):
		return "active"
	default:
		return "expired"
	}
}

// activeAt reports whether the silence covers now, i.e.
// starts_at <= now < ends_at.
func (s *silence) activeAt(now time.Time) bool {
	return !now.Before(s.startsAt) && now.Before(s.endsAt)
}

