	}
	b, _ := json.Marshal(rs.ParentSpanID)
	t.Logf("parent raw: %s nil=%v", b, rs.ParentSpanID == nil)
	batch, ok := decodeSpanBatch([]byte(`{"spans":[` + string(raw) + `]}`))
	t.Logf("ok=%v batch=%v", ok, batch)
}
EOF
